const t=[{id:"compassion-neff-definition",title:"Neff · ¿Qué es la autocompasión? · Dossier C11",url:"https://self-compassion.org/what-is-self-compassion/",type:"guidance",finding:"El modelo reúne amabilidad contigo, reconocer que otras personas también sufren y atender la dificultad sin exagerarla. La compasión tierna y firme son formas prácticas de describir consuelo, protección y acción.",limitation:"Página de definiciones, sin pruebas de mecanismos aislados ni tratamientos. La autoestima puede depender del desempeño, pero eso no define toda autoestima. No exige sentir calidez."},{id:"compassion-mindful-self-compassion-rct",title:"Neff y Germer · 2013 · Ensayo de Autocompasión Consciente · Dossier C05",url:"https://doi.org/10.1002/jclp.21923",type:"research",finding:"52 adultos se asignaron al azar a un programa de ocho semanas o lista de espera. La comparación al terminar favoreció al programa en varias medidas. Las sesiones y el retiro exigían bastante práctica.",limitation:"Ensayo pequeño de un programa completo, dirigido por sus creadores. No probó una pausa ni una carta por separado. Al año respondieron 15 personas, sin grupo de comparación simultáneo. No demuestra que los efectos controlados se mantuvieran para todos."},{id:"compassion-gilbert-cft",title:"Gilbert · 2014 · Terapia centrada en la compasión · Dossier C07",url:"https://doi.org/10.1111/bjc.12043",type:"research",finding:"Revisión clínica y teórica que describe amenaza, impulso y calma vinculada al apoyo como un modelo funcional, junto con prácticas centradas en la compasión.",limitation:"No son tres interruptores anatómicos ni pruebas del efecto aislado de exhalar o imaginar. La protección, los recursos y las necesidades materiales pueden importar. Las prácticas para sentirse a salvo pueden incomodar."},{id:"compassion-tangney-moral-emotions",title:"Tangney, Stuewig y Mashek · 2007 · Emociones morales · Dossier C08",url:"https://doi.org/10.1146/annurev.psych.56.091103.070145",type:"research",finding:"La vergüenza que abarca toda la persona suele relacionarse con aislarse o ponerse a la defensiva. La culpa por una conducta puede relacionarse con empatía y reparación.",limitation:"Revisión narrativa, principalmente observacional. Son tendencias, no leyes absolutas. La culpa excesiva puede hacer daño. Sentir vergüenza tras sufrir una agresión no prueba que hiciste algo malo ni que debas disculparte."},{id:"compassion-brown-shame-resilience",title:"Brown · 2006 · Teoría sobre afrontar la vergüenza · Dossier C09",url:"https://doi.org/10.1606/1044-3894.3483",type:"research",finding:"Entrevistas con 215 mujeres permitieron desarrollar un modelo: reconocer la vergüenza, revisar las expectativas, buscar vínculos seguros y nombrar lo que se siente.",limitation:"Desarrollo teórico cualitativo, sin prueba controlada de un tratamiento de cuatro pasos. Compartir lo vivido es opcional, solo con alguien seguro y dispuesto. No se exige atender al cuerpo ni recordar un trauma."},{id:"compassion-improvement-motivation",title:"Breines y Chen · 2012 · Motivación para mejorar · Dossier C06",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Cuatro experimentos encontraron motivación para mejorar a corto plazo. Tras fallar una prueba, quienes recibieron una indicación compasiva estudiaron más que quienes no recibieron recordatorio: 306.5 frente a 203.2 segundos.",limitation:"Las calificaciones de la segunda prueba no mejoraron de forma estadísticamente significativa. La comparación con autoestima fue inconclusa. Querer reparar no es reparar. No se verificaron cambios duraderos ni una réplica independiente prerregistrada."},{id:"compassion-journal-guidance",title:"Neff · Diario de autocompasión · Dossier C18",url:"https://self-compassion.org/exercises/exercise-6-self-compassion-journal/",type:"technique",finding:"La creadora propone reconocer una dificultad, su contexto humano y palabras amables, escribiendo cada día durante una semana o más.",limitation:"No demuestra eficacia aislada ni que esta versión de ODA se haya probado. Reflexionar antes o durante menos tiempo son adaptaciones. Puedes omitir la escritura o parar si aumenta el malestar."},{id:"compassion-break-guidance",title:"Neff · Pausa de autocompasión · Dossier C16",url:"https://self-compassion.org/exercises/exercise-2-self-compassion-break/",type:"technique",finding:"La creadora propone reconocer el dolor y que otras personas también pasan por dificultades, y ofrecer palabras amables o un deseo. Las instrucciones originales incluyen contacto reconfortante.",limitation:"No es una prueba de eficacia aislada ni una duración eficaz demostrada de dos minutos. ODA ofrece contacto opcional, ejemplos leves, respiración habitual, atención al entorno y opciones para parar."},{id:"compassion-touch-trial",title:"Dreisoerner y colaboradores · 2021 · Ensayo de contacto reconfortante · Dossier C14",url:"https://doi.org/10.1016/j.cpnec.2021.100091",type:"research",finding:"La muestra final tuvo 159 adultos jóvenes sanos. El contacto con el propio cuerpo cambió la respuesta de cortisol a una situación estresante de laboratorio. No hubo diferencias en el estrés informado ni en la frecuencia cardíaca.",limitation:"Un ensayo prerregistrado, con cambios en el análisis de datos faltantes. No midió oxitocina ni demuestra alivio emocional garantizado o eficacia clínica. Respirar normalmente y omitir el contacto son adaptaciones de ODA."},{id:"compassion-kindness-review",title:"Zeng y colaboradores · 2015 · Revisión de meditación de bondad · Dossier C10",url:"https://doi.org/10.3389/fpsyg.2015.01693",type:"research",finding:"24 estudios empíricos con 1,759 participantes combinaron distintos diseños. Las estimaciones de subgrupos de bondad amorosa y compasión fueron 0.424 y 0.286. La diferencia entre subgrupos no fue estadísticamente significativa.",limitation:"No son 24 ensayos aleatorizados ni prueban qué práctica es mejor. Métodos variados, estudios iniciales y frecuentes listas de espera como comparación. No estima los ejercicios de calma de ODA."},{id:"compassion-practice-safety",title:"Neff · Orientación para practicar autocompasión · Dossier C12",url:"https://self-compassion.org/self-compassion-practices/",type:"guidance",finding:"La creadora distingue la intención amable de conseguir sensaciones agradables. Recomienda reducir o dejar la práctica cuando el malestar te sobrepasa.",limitation:"Consejos prácticos, sin un diagnóstico nuevo ni un mecanismo fisiológico demostrado de malestar posterior. Atender al entorno, buscar apoyo cotidiano o parar puede reemplazar la atención interna que incomoda."},{id:"compassion-letter-guidance",title:"Neff · Carta desde la mirada de un amigo · Dossier C17",url:"https://self-compassion.org/exercises/exercise-3-exploring-self-compassion-through-writing/",type:"technique",finding:"La creadora propone la mirada de un amigo que te aprecia, con sugerencias amables para cambiar. Recomienda dejar la carta a un lado y releerla después.",limitation:"No demuestra eficacia aislada ni que quince minutos sea la duración óptima. El ensayo del programa no aisló la carta. No exige contar sufrimiento, sentir calidez o culpa, ni compartir detalles personales."}],s=[{schemaVersion:2,revision:2,id:"compassion-1",courseId:"compassion",locale:"es",title:"¿Fallaste otra vez? Corrige sin insultarte",goal:"Elige una dificultad manejable, descríbela con justicia y da un paso útil para corregir, actuar o pedir apoyo.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Tu voz crítica dice que te exige para mejorar. ¿Qué acción útil salió del último insulto que te dijiste?",reason:{id:"compassion-1-reason",label:"¿Qué respuesta útil has postergado mientras te criticas?",kind:"text",maxLength:160,optional:!0,suggestions:["Corregir un error real","Retomar trabajo útil","Pedir apoyo antes"]},why:{id:"compassion-1-why",label:"¿A qué darías espacio esta semana con este paso?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-1-cost",label:"¿Qué te está costando seguir así?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tratarte bien y esforzarte pueden ir juntos. En un experimento tras fallar una prueba, estudiantes que recibieron una indicación compasiva estudiaron más que quienes no recibieron recordatorio. Las calificaciones siguientes no mejoraron significativamente. Se midió esfuerzo inmediato, sin resultados garantizados.","Trabaja con la misma dificultad cotidiana durante el curso. Conserva el hecho y deja el insulto: «Calculé poco tiempo», en vez de «No sirvo». Luego corrige, retoma una tarea o pide apoyo. Repara el daño que causaste; protégete del que recibiste. Sentirte mejor contigo es opcional. Sigue probando esta acción, su señal y lo que ocurre."],example:{title:"Daniel comunica una nueva fecha",text:"A las 5 p. m., Daniel ve que calculó poco tiempo para su informe. Deja de llamarse «idiota» y describe el error. Desde su escritorio, envía una fecha realista y añade un margen al próximo cálculo. Su jefe está decepcionado. Daniel anota ambos cambios. Sigue lamentando el retraso, pero ya empezó a corregirlo."}},move:{invitation:"Elige una dificultad manejable. Describe el hecho y responde con algo útil, en vez de volver a insultarte.",instructions:["Describe el hecho sin juzgar tu valor como persona.","Corrige, retoma una tarea o pide el apoyo adecuado."],prompts:[],suggestions:{action:["Enviar una nueva fecha realista","Corregir un error real del trabajo","Pedir un apoyo práctico"],minimum:["Enviar una frase con información concreta","Corregir un elemento real","Nombrar una necesidad de apoyo"],cue:["Después de revisar el tiempo que calculé","Ante mi próxima dificultad manejable"],place:["En mi escritorio de trabajo","En una conversación segura por mensaje"],fallback:["Pedir ayuda para calcular el trabajo","Buscar una forma más segura de pedir apoyo"],observation:["La información o corrección que hice","La respuesta que recibí"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],minutes:[3,2,5]},suggested:{action:"Enviar una nueva fecha realista",minimum:"Enviar una frase con información concreta",minutes:3,cueHint:"Después de revisar el tiempo que calculé",placeHint:"En mi escritorio de trabajo",obstacleHint:"Me insulto en vez de atender el error",fallbackHint:"Pedir ayuda para calcular el trabajo",observationHint:"La información o corrección que hice"},stopRule:"Elige una dificultad cotidiana. Para si sientes malestar. Busca apoyo si persiste o te sobrepasa.",accessibleAlternative:"Usa palabras neutras, tu forma habitual de comunicarte o ayuda. No exige calidez, atención al cuerpo ni compartir detalles."},result:{question:"¿Diste el paso útil que elegiste?",observationPrompt:"¿Qué corregiste, pediste o hiciste en realidad?"},judgment:{primary:{id:"compassion-1-missed-estimate",scenario:"Daniel no cumplió una entrega porque subestimó el trabajo. Ahora puede dar una fecha realista y ajustar su cálculo.",question:"¿Qué respuesta combina cuidado y responsabilidad?",bestOptionId:"update-and-adjust",options:[{id:"update-and-adjust",text:"Reconocer el error de cálculo sin insultarse, enviar la fecha realista y ajustar cómo calculará el próximo trabajo.",feedback:"Conserva el impacto real y empieza a corregirlo. Daniel puede lamentar el error mientras informa y mejora su plan. Tratarse bien no exige justificar el retraso."},{id:"wait-for-shame",text:"Descansar esta tarde y preparar un mensaje al equipo cuando la vergüenza le permita hablar de lo ocurrido.",feedback:"Descansar puede ser adecuado, pero ahora puede y necesita informar. Esperar a sentir menos vergüenza deja al equipo sin datos. Envía la fecha realista; después, cuida tu recuperación."},{id:"explain-regret",text:"Explicar cuánto lamenta el retraso y prometer una nueva fecha cuando tenga más claridad sobre el trabajo.",feedback:"Lamentarlo puede formar parte de una disculpa. No reemplaza los datos que Daniel ya tiene. Da la fecha realista y corrige el cálculo, en vez de insistir en castigarte."}]}},carry:{takeaway:"Conserva la exigencia y los hechos. Muestra cuidado con la siguiente acción útil.",followUp:{questionId:"compassion-1-return",question:"¿Las palabras justas ayudaron a actuar, quedaron en palabras o mostraron que necesitabas apoyo o una pausa?",observationPrompt:"Nombra qué informaste, corregiste o pediste; indica si no pudiste hacerlo.",adjustmentPrompt:"¿Qué ajustarías para que el próximo intento encaje en tu vida?"}},goDeeper:{sections:[{heading:"Más esfuerzo no significó mejores calificaciones",paragraphs:["Breines y Chen hicieron cuatro experimentos sobre autocompasión y motivación para mejorar. Tras fallar una prueba, el grupo de compasión estudió un promedio de 306.5 segundos, frente a 203.2 sin recordatorio. La comparación con palabras para reforzar la autoestima fue inconclusa. Las calificaciones de la segunda prueba no mostraron diferencias estadísticamente significativas. El experimento sobre una falta midió las ganas de reparar, no una reparación realizada. [C06: compassion-improvement-motivation]","Estos experimentos breves incluyeron sobre todo estudiantes, además de adultos participantes por internet. No demuestran cambios duraderos ni el efecto de las palabras de esta lección. Cuidarte puede acompañar el esfuerzo, pero una frase justa no garantiza motivación, rendimiento ni reparación. Añadir un paso real es una adaptación de ODA. Informa lo que hiciste, incluso una respuesta poco útil, una corrección incompleta o que no hubo ocasión. Comunicar otra fecha demuestra que informaste; no prueba que terminaste el trabajo pendiente."]},{heading:"Una dificultad y una respuesta que vas ajustando",paragraphs:["Neff describe la autocompasión como amabilidad contigo, reconocer que otras personas también sufren y atender la dificultad sin exagerarla. No exige olvidar un error ni aprobar conductas dañinas. Es una definición y un modelo práctico, sin tres mecanismos demostrados por separado. [C11: compassion-neff-definition] Aquí basta tratarte con respeto: di qué ocurrió y elige qué ayudaría a resolverlo.","Mantén la misma dificultad manejable o conducta que se repite mientras avanzas. Las siguientes lecciones mejoran el apoyo para actuar; no te obligan a sentirte bien. Corrige donde cometiste un error. Pide apoyo o protégete si te hicieron daño o la tarea supera tus recursos. No inventes una disculpa para cumplir el ejercicio. Puedes anotar una reparación intentada, una tarea retomada, una petición de apoyo o una pausa adecuada. Un plan sigue siendo un plan hasta que cuentes lo que hiciste. La respuesta de otra persona queda fuera de tu control."]}],sourceIds:["compassion-improvement-motivation","compassion-neff-definition"]}},{schemaVersion:2,revision:2,id:"compassion-2",courseId:"compassion",locale:"es",title:"Tu decepción cuenta, aunque otros también fallen",goal:"Añade el apoyo que faltó ante la misma dificultad y haz el mínimo útil que ya elegiste.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"«Todos nos equivocamos» también puede servir para ignorar tu dolor. ¿Qué dejó fuera tu respuesta?",reason:{id:"compassion-2-reason",label:"¿Qué dejas de atender cuando restas valor a tu decepción?",kind:"text",maxLength:160,optional:!0,suggestions:["Reconocer lo que dolió","No verme como la única persona que falla","Retomar sin restarle valor a lo que siento"]},why:{id:"compassion-2-why",label:"¿A qué darías espacio esta semana con este paso?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-2-cost",label:"¿Qué te está costando seguir así?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["El modelo de Neff reúne reconocer la dificultad, saber que otros también pasan por ella y responder con ayuda. «Todos fallan, deja de hacer un drama» reconoce que otros sufren, pero descarta tu dolor. Nombrar el dolor sin ofrecer apoyo también deja algo fuera.","Ante la misma dificultad, añade lo que faltó con palabras neutras. «Estoy decepcionada y puedo revisar una pregunta» puede bastar. La autoestima puede depender del desempeño, pero eso no define toda autoestima. No necesitas compararte ni demostrar que vales más. Haz tu mínimo útil o elige apoyo adecuado."],example:{title:"Inés vuelve a una pregunta",text:"Después de cenar, Inés revisa el error del examen que eligió ayer. «Todos fallan» la ayudaba a negar su decepción. En su mesa de la cocina, añade: «Esto duele y puedo ayudarme a entender una pregunta». La revisa dos minutos. Sigue sin gustarle el resultado y necesita practicar más. Anota la revisión, sin puntuar su confianza."}},move:{invitation:"Añade el apoyo que faltó. Úsalo al hacer la misma acción útil.",instructions:["Reconoce la dificultad sin exagerarla ni restarle valor.","Haz el mínimo útil que ya elegiste o busca apoyo adecuado."],prompts:[],suggestions:{action:["Revisar una pregunta que respondí mal","Corregir el elemento de trabajo elegido","Enviar la petición de apoyo prevista"],minimum:["Revisar una pregunta de práctica","Corregir un elemento real","Hacer una petición de apoyo"],cue:["Después de cenar, al revisar","Ante la misma dificultad de antes"],place:["En mi mesa de la cocina","En un lugar seguro para estudiar"],fallback:["Pedir ayuda con la pregunta","Usar palabras neutras y reducir el paso"],observation:["La frase de apoyo y lo que hice","Dónde sigo necesitando ayuda"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],minutes:[2,1,5]},suggested:{action:"Revisar una pregunta que respondí mal",minimum:"Revisar una pregunta de práctica",minutes:2,cueHint:"Después de cenar, al revisar",placeHint:"En mi mesa de la cocina",obstacleHint:"Le resto valor a la dificultad en vez de apoyarme",fallbackHint:"Pedir ayuda con la pregunta",observationHint:"La frase de apoyo y lo que hice"},stopRule:"Omite recuerdos dolorosos y busca apoyo si la práctica te sobrepasa.",accessibleAlternative:"Piensa con palabras neutras, escribe, usa señas o pide ayuda. No exige sensaciones cálidas ni compararte."},result:{question:"¿Hiciste el mínimo útil que elegiste con el apoyo añadido?",observationPrompt:"¿Qué apoyo añadiste y qué hiciste en realidad?"},judgment:{primary:{id:"compassion-2-dismissed-disappointment",scenario:"Inés descarta su decepción del examen diciendo «Todos fallan». Está descansada, tiene cinco minutos libres y una pregunta marcada. Su turno de tarde no deja tiempo para estudiar después.",question:"¿Qué respuesta aprovecha esta ocasión de repasar?",bestOptionId:"acknowledge-and-review",options:[{id:"break-and-review-later",text:"Reconocer la decepción, descansar brevemente del estudio ahora y dejar la pregunta lista para después de su turno.",feedback:"Descansar cuida su capacidad cuando lo necesita. Aquí está descansada y no tendrá tiempo después. Revisa la pregunta disponible ahora; busca cómo descansar alrededor del turno."},{id:"organize-review-topics",text:"Reconocer la decepción y dedicar los cinco minutos a organizar un resumen de temas que necesita practicar más.",feedback:"Un resumen ayuda cuando faltan prioridades. Esta pregunta ya está elegida y lista. Revísala ahora; usa las dificultades que queden para decidir qué repasar después."},{id:"acknowledge-and-review",text:"Reconocer la decepción, recordar que otros también pasan por dificultades y tratarse con justicia mientras revisa la pregunta.",feedback:"Que otras personas sufran no borra la decepción de Inés. Esta respuesta reconoce lo que siente y aporta apoyo para actuar. No necesita compararse ni sentir alivio inmediato."}]}},carry:{takeaway:"Saber que otros también sufren puede aliviar la soledad. Tus necesidades siguen contando.",followUp:{questionId:"compassion-2-return",question:"¿Qué apoyo faltaba y cambió tu siguiente acción útil al añadirlo?",observationPrompt:"Nombra el apoyo y su efecto; indica si lo omitiste o no sabes qué cambió.",adjustmentPrompt:"¿Qué ajustarías para que el próximo intento encaje en tu vida?"}},goDeeper:{sections:[{heading:"Una definición no demuestra tres ingredientes eficaces",paragraphs:["La definición de Neff reúne amabilidad contigo, reconocer que sufrir es parte de la vida humana y atender el sufrimiento sin exagerarlo. Esos nombres describen un modelo. La página de su creadora no demuestra que cada parte aislada cause mejoras clínicas. Tampoco define toda autoestima como competencia. Tu valoración personal puede depender del desempeño o de compararte, pero esa es una posibilidad, no la definición completa. [C11: compassion-neff-definition]","Usa estas tres ideas para revisar cómo respondiste, sin ponerte una calificación como persona. ¿Reconociste lo difícil? ¿Evitaste verlo como prueba de que solo tú tienes algo mal? ¿Ofreciste una respuesta útil? Una frase puede ser neutra y respetuosa si las palabras afectuosas te suenan falsas. Mantén la acción de la lección anterior. Esta aplicación breve de ODA permite informar qué hiciste con ese apoyo. No ofrece un diagnóstico ni una puntuación validada de cada componente."]},{heading:"El diario puede apoyar la acción sin reemplazarla",paragraphs:["El diario de autocompasión de su creadora pide reconocer una dificultad, su contexto humano y palabras amables. Sugiere escribir cada día una semana o más, normalmente por la tarde. Explica cómo enseña la práctica; no demuestra su efecto clínico por separado ni una duración óptima para escribir. [C18: compassion-journal-guidance] Esta lección propone una revisión opcional más breve alrededor de la misma prueba que vienes haciendo.","Escribe solo si ayuda. Puedes responder en silencio, usar comunicación asistida o guardar los detalles fuera de ODA. Si reflexionar te lleva a darle vueltas sin avanzar, cambia la hora o deja la escritura. Escribir es preparación cuando buscas revisar una pregunta, corregir o pedir apoyo. Puedes registrarlo como preparación, pero no demuestra que hiciste la acción posterior. Anota la pregunta revisada, la corrección o la petición enviada. Informar algo urgente y seguir las medidas de seguridad nunca debe esperar a un ejercicio de reflexión personal."]}],sourceIds:["compassion-neff-definition","compassion-journal-guidance"]}},{schemaVersion:2,revision:2,id:"compassion-3",courseId:"compassion",locale:"es",title:"¿La pausa no alivió? Elige cómo cuidarte",goal:"Prueba una pausa de apoyo opcional antes de la misma acción útil. No necesitas sentir alivio para terminar.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"La pausa no borró el dolor. ¿Qué puedes hacer para cuidarte sin pedirte demasiado?",reason:{id:"compassion-3-reason",label:"¿Qué dejas pendiente mientras esperas sentir calma?",kind:"text",maxLength:160,optional:!0,suggestions:["Usar comentarios que me ayudan","Pedir apoyo cuando me sobrepasa","Retomar sin esperar sentir calma"]},why:{id:"compassion-3-why",label:"¿A qué darías espacio esta semana con este paso?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-3-cost",label:"¿Qué te está costando seguir así?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["La pausa de autocompasión reconoce la dificultad, que otros también la viven y una respuesta útil. Son instrucciones de su creadora. El ensayo estudió un programa de ocho semanas, sin aislar una pausa de dos minutos. Su seguimiento incompleto al año no tuvo grupo de comparación.","Ante la misma dificultad cotidiana, prueba: «Esto cuesta. ¿Qué ayudaría?». El contacto, cerrar los ojos, atender al cuerpo y sentir calidez son opcionales. Respira normalmente; mira a tu alrededor si prefieres. Haz tu mínimo útil, adáptalo o pide apoyo. Para si aumenta el malestar. La pausa prepara una decisión; anota lo que hiciste después."],example:{title:"Santiago responde a los comentarios",text:"A las 3 p. m., Santiago recibe comentarios difíciles sobre su borrador. Hace una pausa solo con palabras: «Esto cuesta. ¿Qué ayudaría ahora?». El contacto le incomoda y lo omite. Aún molesto, corrige un error señalado desde su escritorio. Anota la corrección. El borrador necesita otra revisión y la emoción sigue ahí."}},move:{invitation:"Si ayuda, haz una pausa breve. Luego haz tu mínimo, adáptalo o pide apoyo.",instructions:["Usa una dificultad cotidiana leve, sin obligarte a recordar.","Da un siguiente paso útil si las condiciones encajan."],prompts:[],suggestions:{action:["Corregir un error del borrador","Enviar la información concreta que elegí","Hacer la petición de apoyo prevista"],minimum:["Corregir un error señalado","Enviar una frase con información","Nombrar una necesidad de apoyo"],cue:["Después de recibir comentarios cotidianos difíciles","Ante la misma dificultad de antes"],place:["En mi escritorio, en condiciones seguras","En un espacio tranquilo y conocido"],fallback:["Mirar alrededor y usar palabras neutras","Parar y pedir apoyo útil"],observation:["La acción de cuidado que sí hice","Si paré cuando sentí incomodidad"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],minutes:[2,1,5]},suggested:{action:"Corregir un error del borrador",minimum:"Corregir un error señalado",minutes:2,cueHint:"Después de recibir comentarios cotidianos difíciles",placeHint:"En mi escritorio, en condiciones seguras",obstacleHint:"Espero que la pausa haga desaparecer lo que siento",fallbackHint:"Mirar alrededor y usar palabras neutras",observationHint:"La acción de cuidado que sí hice"},stopRule:"Omite el contacto o los recuerdos. Para si sientes malestar y busca apoyo cuando lo necesites.",accessibleAlternative:"Mantén los ojos abiertos, respira normalmente y mira alrededor. No necesitas atender al cuerpo ni sentir calidez."},result:{question:"¿Diste el siguiente paso de cuidado que elegiste?",observationPrompt:"¿Actuaste, adaptaste el paso, paraste o pediste apoyo?"},judgment:{primary:{id:"compassion-3-upset-after-pause",scenario:"Santiago hace una pausa cómoda tras recibir comentarios. Sigue molesto, pero puede corregir sin riesgo un error claro del borrador en dos minutos. Faltan cuatro minutos para revisarlo.",question:"¿Qué cumple el propósito de la pausa?",bestOptionId:"manageable-correction",options:[{id:"pause-and-correct-later",text:"Hacer otra pausa de dos minutos y dejar la corrección para después de la revisión, sin apresurar el borrador.",feedback:"Más tiempo ayuda cuando la tarea supera tu capacidad. Esta corrección segura cabe antes de la revisión. Prueba el mínimo disponible aunque sigas molesto; puedes parar si te sobrepasa."},{id:"manageable-correction",text:"Corregir el error claro aunque siga molesto y pedir apoyo si lo que siente llega a sobrepasarlo.",feedback:"El alivio no es obligatorio. La pausa ayuda a elegir algo posible, incluido pedir apoyo cuando hace falta. Santiago puede anotar la corrección sin afirmar que cambió su emoción."},{id:"review-broader-priorities",text:"Revisar primero las prioridades generales de los comentarios y programar la corrección clara para la próxima sesión del borrador.",feedback:"Mirar el conjunto ayuda a encontrar prioridades. Aquí ya hay una corrección necesaria y clara que cabe antes de la revisión. Hazla ahora; revisa las demás prioridades por separado."}]}},carry:{takeaway:"Una pausa amable ayuda a elegir. No necesita hacerte sentir bien para servirte.",followUp:{questionId:"compassion-3-return",question:"Después de la pausa, ¿actuaste, adaptaste el paso, buscaste apoyo o tuviste que parar?",observationPrompt:"Nombra el siguiente paso real y si hiciste la pausa o la omitiste.",adjustmentPrompt:"¿Qué ajustarías para que el próximo intento encaje en tu vida?"}},goDeeper:{sections:[{heading:"La pausa y el programa son cosas distintas",paragraphs:["Las instrucciones de Neff para una pausa de autocompasión proponen reconocer el dolor, que las dificultades forman parte de la vida humana y palabras amables o un deseo. La versión original incluye contacto reconfortante. No demuestra eficacia aislada ni una duración eficaz de dos minutos. [C16: compassion-break-guidance] Aquí el contacto y recordar son opcionales. Añadir una respuesta práctica es una adaptación de ODA.","El ensayo de Autocompasión Consciente asignó al azar a 52 adultos de la comunidad a un programa de ocho semanas o lista de espera. Incluía sesiones semanales de dos horas y un retiro de cuatro horas, con bastante práctica diaria recomendada. La comparación al terminar favoreció al programa en varias medidas. Solo 15 participantes del programa respondieron al año, sin grupo de comparación simultáneo. Ese seguimiento no prueba que los beneficios controlados se mantuvieran para todos. Tampoco se estudió la pausa por separado. [C05: compassion-mindful-self-compassion-rct] No atribuyas el efecto del programa a esta pausa breve."]},{heading:"El contacto y el alivio van por separado",paragraphs:["Dreisoerner y sus colegas estudiaron el contacto reconfortante con el propio cuerpo antes de una situación estresante de laboratorio, en adultos jóvenes sanos. Las respuestas de cortisol fueron diferentes; el estrés informado y la frecuencia cardíaca no. El ensayo no midió oxitocina ni demostró mejoras clínicas duraderas. Un resultado fisiológico no promete que te sentirás mejor. [C14: compassion-touch-trial] Mantener los ojos abiertos, omitir el contacto y respirar normalmente son opciones de acceso y seguridad. No son el protocolo de contacto estudiado.","Puedes hacerlo solo con palabras, usar lenguaje neutro o fijarte en algo del entorno. No necesitas tocar a otra persona. Si un recuerdo, el contacto o atender a tu interior aumenta la incomodidad, para; no te fuerces a sentir calidez. Elige una actividad sencilla que te cuide o ayuda de alguien. Después puede tocar corregir, pedir apoyo o descansar. Anota esa acción con su propio mínimo. Parar la pausa aporta información; no tienes que demostrar que te esforzaste lo suficiente."]}],sourceIds:["compassion-break-guidance","compassion-mindful-self-compassion-rct","compassion-touch-trial"]}},{schemaVersion:2,revision:2,id:"compassion-4",courseId:"compassion",locale:"es",title:"¿Otra hora trabajando? Cuida lo que estás dejando fuera",goal:"Revisa riesgos reales. Pon un límite práctico o pide apoyo en la misma prueba.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Otra noche trabajando. ¿Atiendes un riesgo real o sigues por miedo?",reason:{id:"compassion-4-reason",label:"¿Qué pierdes con el trabajo extra y qué riesgo real queda?",kind:"text",maxLength:160,optional:!0,suggestions:["Cuidar mi recuperación después del trabajo","Reservar tiempo para quienes quiero","Atender una necesidad real de seguridad"]},why:{id:"compassion-4-why",label:"¿A qué darías espacio esta semana con este paso?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-4-cost",label:"¿Qué te está costando seguir así?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["El modelo de amenaza, impulso y calma de Gilbert es una guía clínica, no tres interruptores cerebrales. Pregúntate si hacer más atiende una necesidad real o alarga lo mismo de siempre. La protección y los recursos pueden influir en tu seguridad; las palabras tranquilizadoras no los reemplazan.","Sigue con la misma dificultad o conducta repetida. Si siempre trabajas de más, revisa fechas y consecuencias antes de elegir cuándo parar. Un peligro real exige ayuda práctica. Respirar de otra manera e imaginar son opcionales; puede bastar mirar alrededor. Cumple el límite o pide apoyo sin exigir calma, aprobación ni tener todos los correos resueltos."],example:{title:"Mariana termina su jornada",text:"A las 9 p. m., Mariana ve en sus notas que volvió a trabajar hasta tarde. No hay entregas urgentes. Sentada, mira la lámpara, anota la primera prioridad de mañana y cierra las aplicaciones de trabajo. Sigue preocupada. Deja el escritorio para descansar como planeó y anota el límite cumplido. Un correo espera hasta mañana."}},move:{invitation:"Revisa el riesgo real. Cumple un límite o pide apoyo.",instructions:["Revisa fechas, seguridad y responsabilidades antes de elegir un límite.","Cumple un límite o haz una petición de apoyo."],prompts:[],suggestions:{action:["Cerrar aplicaciones de trabajo al terminar","Pedir una medida práctica de protección","Comunicar un límite posible para una tarea"],minimum:["Cerrar las aplicaciones y alejarme","Hacer una petición de apoyo","Decir un límite posible para la tarea"],cue:["A la hora que elegí para terminar","Cuando se repita mi conducta habitual"],place:["En mi escritorio de trabajo","Por una vía segura de apoyo"],fallback:["Aclarar una responsabilidad realmente urgente","Pedir ayuda para poner el límite sin riesgo"],observation:["Si cumplí el límite elegido","Qué riesgo real apareció"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],minutes:[2,1,5]},suggested:{action:"Cerrar aplicaciones de trabajo al terminar",minimum:"Cerrar las aplicaciones y alejarme",minutes:2,cueHint:"A la hora que elegí para terminar",placeHint:"En mi escritorio de trabajo",obstacleHint:"Sigo trabajando hasta que se vaya la preocupación",fallbackHint:"Aclarar una responsabilidad realmente urgente",observationHint:"Si cumplí el límite elegido"},stopRule:"Deja de fijarte en la respiración o imaginar si incomoda. Un peligro real necesita protección práctica y apoyo.",accessibleAlternative:"Quédate sentado, con los ojos abiertos, y mira alrededor mientras respiras normalmente. No exige imágenes ni calidez."},result:{question:"¿Cumpliste el límite o hiciste la petición que elegiste?",observationPrompt:"¿Qué límite pusiste y qué consecuencia real tuvo?"},judgment:{primary:{id:"compassion-4-no-urgent-deadline",scenario:"Mariana sigue trabajando por miedo a las críticas. Ya revisó las fechas; no queda nada urgente. Eligió una hora para terminar y cuidar su recuperación.",question:"¿Qué paso pone a prueba ese límite?",bestOptionId:"priority-and-close",options:[{id:"priority-and-close",text:"Anotar la primera prioridad de mañana y cerrar las aplicaciones a la hora elegida, aunque siga preocupada.",feedback:"Cambia la conducta repetida y conserva la tarea de mañana. Mariana puede probar un límite posible sin resolver todos los correos ni forzar calma. Un riesgo urgente real requeriría otra respuesta."},{id:"finish-tomorrow-task",text:"Terminar esta noche la primera prioridad de mañana para poder parar con la certeza de haber cubierto lo importante.",feedback:"Terminar puede parecer más seguro, pero ninguna fecha urgente lo exige. Alarga justo lo que el límite busca cambiar. Anota la prioridad y prueba parar a la hora acordada."},{id:"scan-before-closing",text:"Cerrar las aplicaciones después de revisar el correo cinco minutos para confirmar que no pasó por alto ninguna entrega.",feedback:"Revisar ayuda cuando no sabes si hay urgencia. Mariana ya comprobó las fechas. Otra revisión retrasa el límite elegido. Anota la prioridad de mañana y cierra las aplicaciones."}]}},carry:{takeaway:"Revisa el riesgo real. Cuídate con un límite práctico, recursos o una petición de apoyo.",followUp:{questionId:"compassion-4-return",question:"¿Probaste el límite? ¿Apareció un riesgo nuevo, siguió sin haberlo o no quedó claro?",observationPrompt:"¿Qué tiempo o recurso protegiste y qué consecuencia real apareció?",adjustmentPrompt:"¿Qué ajustarías para que el próximo intento encaje en tu vida?"}},goDeeper:{sections:[{heading:"Una guía clínica, no tres interruptores cerebrales",paragraphs:["La revisión clínica de Gilbert usa amenaza, búsqueda o impulso y calma vinculada al apoyo como un modelo funcional simplificado. Describe terapia centrada en la compasión y ejercicios prácticos. No es un experimento que demuestre tres circuitos cerebrales separados, el efecto aislado de exhalar ni un interruptor literal que apague la amenaza. [C07: compassion-gilbert-cft] La respiración cómoda y las imágenes compasivas pueden ser prácticas opcionales, con permiso para parar enseguida.","El modelo tampoco decide si un peligro es real. Problemas de vivienda, ingresos insuficientes, necesidades de salud o una relación insegura pueden exigir recursos y cambios prácticos. La protección y los recursos pueden influir en tu seguridad. Revisa qué lograrías realmente trabajando más aquí. Sin responsabilidades urgentes pendientes, un límite puede ser una prueba útil. Si queda riesgo, protegerte o pedir apoyo puede ser la forma de cuidarte. Tus notas ayudan a distinguir estos casos. Anotar una prioridad prepara el cierre; cerrar las aplicaciones y alejarte del trabajo lo cumple."]},{heading:"Sin una meditación ganadora ni calidez obligatoria",paragraphs:["Zeng y sus colegas revisaron 24 estudios empíricos con 1,759 participantes y distintos diseños. En un análisis pertinente de subgrupos, la estimación de bondad amorosa fue 0.424; la de compasión, 0.286. La diferencia no fue estadísticamente significativa. Las cifras no demuestran que una práctica sea mejor. Tampoco prueban que la compasión no tenga efecto ni estiman un ejercicio de calma de ODA. [C10: compassion-kindness-review]","La orientación de la creadora distingue la intención amable de producir sensaciones agradables. Recomienda reducir o dejar la práctica cuando te sobrepasa. [C12: compassion-practice-safety] Puedes atender al entorno, hacer una actividad cotidiana o buscar apoyo en vez de imaginar. No presentes la incomodidad como un mecanismo fisiológico de malestar posterior ni un diagnóstico nuevo. Aquí observas el límite cumplido o la petición práctica realizada. Puede seguir la preocupación después de parar, y alguien puede no estar de acuerdo. Usa lo observado para ajustar la próxima prueba, sin exigirte sentir calidez."]}],sourceIds:["compassion-gilbert-cft","compassion-kindness-review","compassion-practice-safety"]}},{schemaVersion:2,revision:2,id:"compassion-5",courseId:"compassion",locale:"es",title:"¿Sientes vergüenza? Revisa de quién es la responsabilidad",goal:"Revisa tu responsabilidad ante la misma dificultad. Luego repara, protégete o pide apoyo.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Evitas reparar un daño que causaste o aceptas una culpa ajena? Empieza por los hechos.",reason:{id:"compassion-5-reason",label:"¿Qué pasarías por alto o aceptarías con una culpa mal puesta?",kind:"text",maxLength:160,optional:!0,suggestions:["Reparar el daño que sí causé","Rechazar una culpa injusta","Pedir apoyo seguro"]},why:{id:"compassion-5-why",label:"¿A qué darías espacio esta semana con este paso?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-5-cost",label:"¿Qué te está costando seguir así?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sentir vergüenza de quién eres suele relacionarse con esconderte o ponerte a la defensiva. La culpa por una conducta puede relacionarse con empatía y reparación. Son tendencias: la culpa excesiva puede hacer daño. Sentir vergüenza tras sufrir una agresión no prueba que hiciste algo malo.","Vuelve a la misma dificultad. Revisa qué hiciste y si causó daño. Repara lo que te corresponde; busca protección o apoyo ante el maltrato. Puedes nombrar la emoción en privado y revisar lo que se esperaba. Contarlo es opcional, solo con alguien seguro y dispuesto. Da un paso adecuado. Cambiar las palabras no completa una reparación."],example:{title:"Julián revisa qué le corresponde",text:"Al almorzar, Julián recuerda un comentario hiriente que hizo a un compañero. Identifica las palabras y su efecto sin llamarse mala persona. Por mensaje privado, se disculpa por ese comentario y corrige la información que dio. El compañero no responde ese día. Julián anota la reparación sin pedir que lo tranquilicen ni lo perdonen."}},move:{invitation:"Revisa los hechos. Si causaste daño, repara; si no, elige protección o apoyo.",instructions:["Revisa tu responsabilidad real antes de decidir si corresponde disculparte.","Repara, protégete o pide apoyo de forma segura."],prompts:[],suggestions:{action:["Reparar un daño que causé","Hacer una petición segura de apoyo","Cumplir un límite que me proteja"],minimum:["Reparar un daño que causé","Hacer una petición de apoyo","Decir un límite seguro"],cue:["Después de revisar mi responsabilidad real","Ante la misma dificultad de antes"],place:["En un mensaje privado y seguro","En mi espacio de apoyo de confianza"],fallback:["Buscar apoyo antes de un contacto inseguro","Corregir sin riesgo ni compartir detalles privados"],observation:["Los hechos y la respuesta que elegí","La reparación o protección que sí hice"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],minutes:[2,1,5]},suggested:{action:"Reparar un daño que causé",minimum:"Reparar un daño que causé",minutes:2,cueHint:"Después de revisar mi responsabilidad real",placeHint:"En un mensaje privado y seguro",obstacleHint:"Tomo la vergüenza como prueba de haber causado daño",fallbackHint:"Buscar apoyo antes de un contacto inseguro",observationHint:"Los hechos y la respuesta que elegí"},stopRule:"Sentir vergüenza no te obliga a disculparte, perdonar ni tener contacto inseguro. Busca protección ante el peligro.",accessibleAlternative:"Puedes reflexionar en privado. Usa palabras neutras, escribe, usa señas o pide ayuda. Compartir detalles y atender al cuerpo son opcionales."},result:{question:"¿Diste el siguiente paso adecuado que elegiste?",observationPrompt:"¿Qué responsabilidad mostraron los hechos y qué hiciste en realidad?"},judgment:{primary:{id:"compassion-5-imposed-shame",scenario:"Un compañero se burla de Inés en público después de una observación correcta. Ella siente vergüenza. Los hechos no muestran ningún error ni daño que haya causado.",question:"¿Qué siguiente paso corresponde?",bestOptionId:"support-not-blame",options:[{id:"apologize-tension",text:"Disculparse por contribuir a la tensión para darle al compañero la oportunidad de responder de una forma más constructiva.",feedback:"Reparar exige una responsabilidad real. Aquí no se indica ninguna de Inés. Disculparse inventaría culpa y ocultaría la burla. Considera apoyo o un límite seguro."},{id:"normalize-and-ignore",text:"Recordar que todos tienen días difíciles y dejar pasar lo ocurrido para conservar una buena relación de trabajo.",feedback:"Compartir dificultades humanas no justifica el maltrato ni decide qué es seguro. Inés puede tener en cuenta el contexto y buscar apoyo adecuado. No necesita confrontar al compañero directamente."},{id:"support-not-blame",text:"Reconocer la vergüenza, conservar los hechos claros y elegir apoyo seguro o un límite, sin inventarse una falta.",feedback:"La vergüenza no prueba culpabilidad. Inés puede atender la burla por una vía segura sin disculparse por un error inexistente ni demostrar que merece un trato respetuoso."}]}},carry:{takeaway:"Cuida tus emociones. La responsabilidad necesita hechos. Después repara, protégete o pide apoyo.",followUp:{questionId:"compassion-5-return",question:"¿Los hechos pedían reparar, protegerte, buscar apoyo práctico o aclarar algo más?",observationPrompt:"Nombra qué elegiste y qué hiciste, sin contar detalles que prefieres guardar para ti.",adjustmentPrompt:"¿Qué ajustarías para que el próximo intento encaje en tu vida?"}},goDeeper:{sections:[{heading:"La vergüenza y la culpa describen tendencias",paragraphs:["Tangney y sus colegas revisaron emociones morales y conducta, principalmente con investigación observacional. La vergüenza que abarca toda la persona solía relacionarse con aislarse o ponerse a la defensiva. La culpa centrada en una conducta podía relacionarse con empatía y reparación. Importan el contexto y cómo se mide. No demuestra que la vergüenza siempre destruya ni que la culpa siempre ayude. Una culpa excesiva o repetitiva también puede hacer daño. [C08: compassion-tangney-moral-emotions]","Puedes sentir vergüenza tras abuso, exclusión, discriminación o enfermedad sin haber hecho nada malo. No conviertas esa emoción en una frase de culpabilidad para encajar en un ejercicio de reparación. Primero identifica una conducta real y sus consecuencias. Una disculpa proporcionada puede corresponder al daño que causaste, sin exigir consuelo ni perdón. Si te imponen culpa, apoyo y protección pueden ser más adecuados. Cambiar una frase no demuestra que la vergüenza se volvió una culpa útil por ese cambio ni prueba que reparaste el daño."]},{heading:"Compartir es opcional y requiere seguridad",paragraphs:["Brown desarrolló su teoría sobre afrontar la vergüenza a partir de entrevistas con 215 mujeres. Reconocer la vergüenza y qué la despierta, revisar expectativas, buscar vínculos seguros y nombrar la emoción forman parte de este modelo cualitativo y práctico. La fuente no verifica un ensayo controlado del tratamiento de cuatro pasos ni demuestra que obligarte a compartir mejore los resultados. [C09: compassion-brown-shame-resilience]","Usa lo que sirva para tu próxima decisión. No necesitas recordar un trauma, revisar sensaciones corporales ni contar una historia. Puede ayudar alguien seguro y dispuesto, pero quizá no tengas a esa persona disponible. Puedes reflexionar en privado, pedir apoyo profesional, corregir un hecho o poner un límite protector. No compartas con quien te maltrata o puede usarlo en tu contra. La vergüenza persistente o que te sobrepasa merece apoyo profesional. La prueba que sigues haciendo pregunta qué acción adecuada realizaste y qué mostró la respuesta. No exige nombrar cada emoción ni completar una secuencia."]}],sourceIds:["compassion-tangney-moral-emotions","compassion-brown-shame-resilience"]}},{schemaVersion:2,revision:2,id:"compassion-6",courseId:"compassion",locale:"es",title:"¿Otra nota amable? Haz algo concreto con su consejo",goal:"Revisa tus intentos de la misma prueba y da un paso posible para reparar, protegerte o pedir apoyo.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Una nota amable puede ayudar. ¿Qué cambio útil te pide hacer hoy lo que escribiste?",reason:{id:"compassion-6-reason",label:"¿Qué cambio útil postergarías escribiendo otra nota?",kind:"text",maxLength:160,optional:!0,suggestions:["Cumplir una reparación real","Mantener un límite que puedo cumplir","Pedir apoyo en vez de atacarme"]},why:{id:"compassion-6-why",label:"¿A qué darías espacio esta semana con este paso?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"compassion-6-cost",label:"¿Qué te está costando seguir así?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["La creadora propone escribir desde la mirada de un amigo, con cuidado y consejos para cambiar. Quince minutos no es una duración óptima verificada. El ensayo del programa no aisló la carta ni mantuvo un grupo de comparación al año.","Revisa tus notas sobre la misma conducta. ¿Qué respuesta llevó a reparar, protegerte, trabajar o pedir apoyo? Conserva lo útil y cambia un obstáculo. En una nota opcional, nombra lo ocurrido, su contexto y un paso que te cuide. Hazlo si corresponde; elige la próxima ocasión realista. No exige calidez, perdón ni una racha perfecta."],example:{title:"Rosa ajusta su próximo intento",text:"El domingo a las 7 p. m., Rosa revisa sus notas sobre cartas de trámites que evitaba. Una nota breve con hechos ayudó; repetir críticas, no. En la mesa de la cocina, escribe cuatro frases amables, corrige un error de archivo y pide ayuda con un aviso confuso. Quedan cartas. Mantiene su mínimo para el miércoles, sin prometer alivio inmediato."}},move:{invitation:"Revisa tus intentos. Ajusta un obstáculo y actúa.",instructions:["Usa intentos reales. Si falta un resultado, no lo inventes.","Haz algo concreto: repara, protégete, trabaja o pide apoyo."],prompts:[],suggestions:{action:["Corregir el siguiente elemento práctico","Usar el límite protector que ya probé","Enviar mi petición específica de apoyo"],minimum:["Corregir un elemento real","Decir un límite que puedo cumplir","Hacer una petición específica"],cue:["Después de revisar mis intentos reales","Ante mi próxima señal que ya funcionó"],place:["En mi mesa de la cocina","Por mi vía segura de apoyo"],fallback:["Pedir ayuda con el obstáculo","Reducir el paso o pausar a propósito"],observation:["El paso y el apoyo que sí usé","Qué conservé o cambié"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],minutes:[3,2,5]},suggested:{action:"Corregir el siguiente elemento práctico",minimum:"Corregir un elemento real",minutes:3,cueHint:"Después de revisar mis intentos reales",placeHint:"En mi mesa de la cocina",obstacleHint:"Escribo para consolarme y dejo pendiente el cambio útil",fallbackHint:"Pedir ayuda con el obstáculo",observationHint:"El paso y el apoyo que sí usé"},stopRule:"Para los recuerdos dolorosos o la escritura si sientes malestar. Reparar exige responsabilidad real; quizá corresponda protegerte.",accessibleAlternative:"La carta es opcional. Piensa cuatro frases neutras, escribe, usa señas o pide ayuda. No necesitas sentir calidez."},result:{question:"¿Diste el siguiente paso práctico que elegiste?",observationPrompt:"¿Qué conservaste, cambiaste o pediste y qué ocurrió en realidad?"},judgment:{primary:{id:"compassion-6-boundary-after-review",scenario:"Rosa revisó su presupuesto: prestar dinero quitaría lo necesario para sus gastos básicos de esta semana. No hay ninguna petición pendiente. Puede separar esos fondos hoy sin contactar a nadie.",question:"¿A qué debe llevar esta revisión?",bestOptionId:"reserve-essential-funds",options:[{id:"draft-future-refusal",text:"Preparar una negativa amable y clara para la próxima petición, dejando el dinero disponible hoy hasta que llegue ese momento.",feedback:"Preparar la negativa ayuda con un límite posterior. Eso deja disponible para prestar el dinero de gastos básicos. Sepáralo ahora y registra cualquier conversación posterior como una acción distinta."},{id:"reserve-essential-funds",text:"Separar hoy el dinero para gastos básicos y preparar un límite seguro por si alguien lo pide después.",feedback:"Separar el dinero cambia cuánto puede prestar hoy. Escribir el límite o ensayar el mensaje solo prepara. No requiere contactar ahora ni prometer que te sentirás mejor."},{id:"budget-and-support",text:"Revisar el presupuesto con alguien de confianza antes de decidir qué límite pondrá a los préstamos que le pidan.",feedback:"El apoyo ayuda si no sabes cuánto puedes prestar o si es seguro. Rosa ya sabe que afectaría gastos básicos y puede separar el dinero sin riesgo hoy. Pide ayuda después para futuras peticiones."}]}},carry:{takeaway:"Cuídate sin ocultar la verdad. Usa tus notas para ajustar el próximo paso.",followUp:{questionId:"compassion-6-return",question:"¿Qué respuesta práctica elegiste para tu próximo intento y qué condición vale la pena repetir?",observationPrompt:"Nombra qué hiciste. El límite escrito sigue siendo preparación hasta que lo uses.",adjustmentPrompt:"¿Qué ajustarías para que el próximo intento encaje en tu vida?"}},goDeeper:{sections:[{heading:"La carta opcional ayuda a tomar una decisión real",paragraphs:["La carta de Neff invita a escribir desde la mirada de alguien que conoce tus fortalezas, dificultades y circunstancias. Incluye consejos amables para cambiar y dejarla a un lado para releer después. La página explica un ejercicio, sin probar su eficacia aislada ni una duración óptima de quince minutos. [C17: compassion-letter-guidance] Las cuatro frases opcionales y el paso práctico posterior son adaptaciones de ODA.","Si escribes, elige una dificultad cotidiana manejable. No necesitas enumerar inseguridades, contar tu sufrimiento, sentir afecto incondicional ni tener un amigo disponible. Puede bastar el respeto: describe la verdad, el contexto pertinente, el cuidado útil y la siguiente acción adecuada. Reparar corresponde a tu responsabilidad real. Protegerte corresponde cuando hace falta un límite o seguridad. Puedes registrar la carta como preparación; la corrección o petición de apoyo tiene su propio mínimo. Un límite escrito sobre préstamos sigue siendo preparación hasta que separes los recursos o lo uses en una ocasión segura."]},{heading:"Tus notas orientan la próxima semana",paragraphs:["Neff llama tierna y firme a dos maneras prácticas de cuidar: consolar y aceptar, junto con proteger, poner límites y seguir metas. No son sistemas cerebrales demostrados por separado. [C11: compassion-neff-definition] Usa esos nombres solo si ayudan a revisar tu conducta real. Una nota consoladora que posterga un cambio necesario y un plan duro que ignora tu capacidad pueden necesitar ajustes.","El estudio de Autocompasión Consciente comparó un programa de ocho semanas con una lista de espera. Su seguimiento incompleto al año no tuvo grupo de comparación simultáneo; no demuestra un efecto duradero de la carta. [C05: compassion-mindful-self-compassion-rct] Por eso el cierre usa los intentos que realmente informaste. Conserva una respuesta útil, cambia un obstáculo y elige una próxima ocasión con fecha. No necesitas añadir rituales ni compensar una pausa. Si siguen faltando recursos, ayuda o apoyo profesional, reconoce esa necesidad. Terminar el curso no prueba reparación, alivio ni práctica. Deja que el próximo registro muestre qué pasó."]}],sourceIds:["compassion-letter-guidance","compassion-neff-definition","compassion-mindful-self-compassion-rct"]}}],c=[{id:"compassion-1",correct:0,photo:{id:"1474418397713-7ede21d49118",alt:"Una persona sentada en una roca mira el amanecer sobre las montañas"},practiceCount:3},{id:"compassion-2",correct:0,photo:{id:"1529156069898-49953e39b3ac",alt:"Amigos abrazados por los hombros, vistos de espaldas"},practiceCount:3},{id:"compassion-3",correct:0,photo:{id:"1499209974431-9dddcece7f88",alt:"Una persona abre los brazos hacia el sol del atardecer"},practiceCount:3},{id:"compassion-4",correct:0,photo:{id:"1441974231531-c6227db76b6e",alt:"La luz del sol atraviesa un bosque tranquilo"},practiceCount:3},{id:"compassion-5",correct:0,photo:{id:"1544027993-37dbfe43562a",alt:"Dos manos se acercan una a la otra"},practiceCount:3},{id:"compassion-6",correct:0,photo:{id:"1455390582262-044cdead277a",alt:"Una mano escribe con bolígrafo en un cuaderno"},practiceCount:3}];function u(a,n){const e=c[n],r=a.judgment.primary.options.find(o=>o.id===a.judgment.primary.bestOptionId),i=a.judgment.primary.options.filter(o=>o.id!==r.id).map(o=>o.text);return i.splice(e.correct,0,r.text),{id:e.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,practice:[a.move.instructions[0],a.move.suggested.action,"Anota lo que ocurrió y elige el siguiente intento adecuado."].slice(0,e.practiceCount),reflection:a.direction.reason.label,question:`${a.judgment.primary.scenario} ${a.judgment.primary.question}`,options:i,correct:e.correct,feedback:r.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,photo:e.photo}}const d={id:"compassion",title:"¿Otro error? Corrige sin insultarte",subtitle:"6 lecciones. Trabaja con una dificultad para reparar, protegerte o pedir apoyo, sin exigirte sentir más calidez.",description:"Conserva la exigencia y los hechos sin despreciarte. Sigue una misma prueba para cuidarte con acciones útiles, revisar tu responsabilidad y dar el siguiente paso adecuado.",scope:"Para adultos que se tratan con dureza después de errores, dificultades o momentos dolorosos. Es educación y práctica personal, no terapia. Si vives con trauma, abuso o vergüenza persistente o que te sobrepasa, busca un profesional capacitado. Los ejercicios de autocompasión pueden despertar dolor antiguo. Si estás en crisis o piensas hacerte daño, llama ahora al número local de emergencias.",outcome:"Una respuesta justa ante una dificultad repetida, una acción adecuada para reparar o protegerte y un próximo intento posible.",photo:{id:"1470252649378-9c29740c9fa8",alt:"Un campo tranquilo bajo la luz cálida del atardecer"},lang:"es",lessons:s.map(u)},l=Object.freeze(Object.defineProperty({__proto__:null,COURSE:d,LESSONS_V2:s,SOURCES:t},Symbol.toStringTag,{value:"Module"}));export{l as c};
